private byte[] canonicalEnvelope(Envelope env, long pn, long expected, byte[] payload) {
    int w = choosePnWidth(pn, expected);
    byte[] pnb = new byte[w];
    for (int i=0;i<w;i++) pnb[w-1-i] = (byte)(pn >>> (8*i));
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    if (env.level == 2) {
        out.write(0x40 | (env.phase << 2) | (w-1));
        out.write(env.dcid, 0, env.dcid.length);
        out.write(pnb,0,w);
    } else {
        out.write((env.level==0?0xc0:0xe0) | (w-1));
        out.write(new byte[]{0,0,0,1},0,4);
        out.write(env.dcid.length); out.write(env.dcid,0,env.dcid.length);
        out.write(env.scid.length); out.write(env.scid,0,env.scid.length);
        if (env.level==0) { writeVar(out, env.token.length); out.write(env.token,0,env.token.length); }
        writeVar(out, w + payload.length);
        out.write(pnb,0,w);
    }
    out.write(payload,0,payload.length);
    return out.toByteArray();
}
