import de.rub.nds.tlsattacker.core.quic.frame.NewConnectionIdFrame;
import de.rub.nds.tlsattacker.core.quic.frame.QuicFrame;
import de.rub.nds.tlsattacker.core.quic.frame.ResetStreamFrame;
import de.rub.nds.tlsattacker.core.quic.frame.RetireConnectionIdFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StopSendingFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StreamDataBlockedFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StreamFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StreamsBlockedFrame;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * Offline layered receive audit: envelope framing, packet number reconstruction, routing,
 * authentication, key epochs, transactional frame effects and canonical wire output.
 */
public final class ReceiveAudit {

    private static final long MAX62 = (1L << 62) - 1;
    private static final long MAX60 = 1L << 60;
    private static final int I = 0;
    private static final int H = 1;
    private static final int A = 2;
    private static final String[] LEVEL = {"I", "H", "A"};
    private static final String EMPTY_HASH =
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

    // ---------------------------------------------------------------- configuration
    private long limitConnection;
    private long limitStream;
    private long limitBidi;
    private long limitUni;
    private int limitCids;
    private long localBidi;
    private long localUni;
    private int localCidWidth;
    private int localCidCount;
    private Map<String, Integer> localCidIndex = new HashMap<>();

    // ---------------------------------------------------------------- connection state
    private final boolean[] activeKeys = new boolean[3];
    private long currentEpoch;
    private final long[] largest = {-1, -1, -1};
    @SuppressWarnings("unchecked")
    private final Set<Long>[] seen = new Set[] {new HashSet<Long>(), new HashSet<Long>(), new HashSet<Long>()};
    private final RangeSet[] acks = {new RangeSet(), new RangeSet(), new RangeSet()};
    private final long[][] ecn = new long[3][3];
    private final TreeMap<Long, long[]> epochs = new TreeMap<>();
    private final TreeMap<Long, StreamState> streams = new TreeMap<>();
    private final ByteStore[] crypto = {new ByteStore(), new ByteStore(), new ByteStore()};
    private long used;
    private long openedBidi;
    private long openedUni;
    private long sendMaxData;
    private long sendMaxStreamsBidi;
    private long sendMaxStreamsUni;
    private final TreeMap<Long, PeerCid> peerCids = new TreeMap<>();
    private final Map<String, Long> cidOwners = new HashMap<>();
    private final TreeSet<Long> activePeer = new TreeSet<>();
    private long retirePriorTo;
    private final TreeSet<Integer> retiredLocal = new TreeSet<>();
    private boolean closed;
    private Map<String, Object> closedRow;

    // ---------------------------------------------------------------- packet transaction
    private final List<Undo> journal = new ArrayList<>();
    private final Map<Long, StreamState> savedStreams = new HashMap<>();
    private final RangeSet[] pendingAck = {new RangeSet(), new RangeSet(), new RangeSet()};
    private final long[][] pendingEcn = new long[3][3];
    private final boolean[] pendingEcnTouched = new boolean[3];
    private long savedUsed;
    private long savedOpenedBidi;
    private long savedOpenedUni;
    private long savedSendMaxData;
    private long savedSendMaxStreamsBidi;
    private long savedSendMaxStreamsUni;
    private long savedRetirePriorTo;

    private final MessageDigest digest = newDigest();


    private static MessageDigest newDigest() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    // ---------------------------------------------------------------- small state holders
    private static final class StreamState {
        long high;
        Long fin;
        Long reset;
        Long stop;
        long sendMax;
        /** Shared with transactional copies; the ledger journals its own mutations. */
        final ByteStore bytes;

        StreamState() {
            this.bytes = new ByteStore();
        }

        private StreamState(ByteStore bytes) {
            this.bytes = bytes;
        }

        StreamState copy() {
            StreamState c = new StreamState(bytes);
            c.high = high;
            c.fin = fin;
            c.reset = reset;
            c.stop = stop;
            c.sendMax = sendMax;
            return c;
        }
    }

}

private static final class PeerCid {
    final byte[] cid;
    final byte[] token;

    PeerCid(byte[] cid, byte[] token) {
        this.cid = cid;
        this.token = token;
    }
}

private static final class Envelope {
    int level;
    byte[] dcid = new byte[0];
    byte[] scid = new byte[0];
    byte[] token = new byte[0];
    byte[] payload = new byte[0];
    long rawPn;
    int pnWidth;
    int phase;
    int next;
    int destSeq = -1;
}

private static final class Frames {
    byte[] payload;
    boolean close;
    int closeOffset;
}

// ================================================================ entry point
public Map<String, Object> audit(Main.Trace trace) {
    configure(trace);
    List<Object> packets = new ArrayList<>();
    List<Object> datagrams = new ArrayList<>();
    for (int event = 0; event < trace.events.size(); event++) {
        Main.Event e = trace.events.get(event);
        if (e.keys != null) {
            if (!closed) {
                activeKeys[I] = e.keys.contains("I");
                activeKeys[H] = e.keys.contains("H");
                activeKeys[A] = e.keys.contains("A");
            }
        } else {
            processDatagram(event, e, packets, datagrams);
        }
    }
    return result(packets, datagrams);
}

private void configure(Main.Trace t) {
    limitConnection = t.connection;
    limitStream = t.stream;
    limitBidi = t.bidi;
    limitUni = t.uni;
    limitCids = t.cidLimit;
    localBidi = t.localBidi;
    localUni = t.localUni;
    localCidCount = t.localCids.size();
    for (int i = 0; i < localCidCount; i++) {
        localCidIndex.put(Main.hex(t.localCids.get(i)), i);
    }
    localCidWidth = t.localCids.get(0).length;
    activeKeys[I] = true;
    for (int level = 0; level < 3; level++) {
        long seed = t.received[level];
        if (seed >= 0) {
            largest[level] = seed;
            seen[level].add(seed);
            if (level == A) {
                epochs.put(0L, new long[] {seed, seed, 1});
            }
        }
    }
    peerCids.put(0L, new PeerCid(t.peerCid, t.peerToken));
    cidOwners.put(Main.hex(t.peerCid), 0L);
    activePeer.add(0L);
}

// ================================================================ datagram level
private void processDatagram(int event, Main.Event e, List<Object> packets, List<Object> datagrams) {
    byte[] wire = e.wire;
    List<Long> auth = e.auth;
    int pos = 0;
    int index = 0;
    int accepted = 0;
    ByteArrayOutputStream acceptedBytes = new ByteArrayOutputStream();
    while (pos < wire.length) {
        int headerOffset = pos;
        Envelope env = parseHeader(wire, pos);
        if (env == null) {
            packets.add(row(event, index, headerOffset, null, null, null, "BAD_HEADER", null));
            index++;
            break;
        }
        pos = env.next;
        if (processEnvelope(event, index, headerOffset, env, auth, packets, acceptedBytes)) {
            accepted++;
        }
        index++;
    }
    byte[] all = acceptedBytes.toByteArray();
    datagrams.add(Main.object("event", (long) event, "packets", (long) index, "accepted", (long) accepted,
            "bytes", (long) all.length, "sha256", hash(all)));
}

/** Parses one envelope header; returns null when the attempt is a BAD_HEADER. */
private Envelope parseHeader(byte[] w, int pos) {
    Envelope env = new Envelope();
    int first = w[pos] & 0xff;
    if ((first & 0x80) != 0) {
        if ((first & 0x40) == 0 || (first & 0x0c) != 0) {
            return null;
        }
        int type = (first & 0x30) >>> 4;
        if (type == 0) {
            env.level = I;
        } else if (type == 2) {
            env.level = H;
        } else {
            return null;
        }
        env.pnWidth = (first & 0x03) + 1;
        int p = pos + 1;
        if (p + 4 > w.length) {
            return null;
        }
        if (w[p] != 0 || w[p + 1] != 0 || w[p + 2] != 0 || w[p + 3] != 1) {
            return null;
        }
        p += 4;
        int dcidLength = readByte(w, p++);
        if (dcidLength < 0 || dcidLength > 20 || p + dcidLength > w.length) {
            return null;
        }
        env.dcid = Arrays.copyOfRange(w, p, p + dcidLength);
        p += dcidLength;
        int scidLength = readByte(w, p++);
        if (scidLength < 0 || scidLength > 20 || p + scidLength > w.length) {
            return null;
        }
        env.scid = Arrays.copyOfRange(w, p, p + scidLength);
        p += scidLength;
        if (env.level == I) {
            long[] tokenLength = readVarint(w, p);
            if (tokenLength == null) {
                return null;
            }
            p = (int) tokenLength[1];
            if (tokenLength[0] > (long) (w.length - p)) {
                return null;
            }
            env.token = Arrays.copyOfRange(w, p, p + (int) tokenLength[0]);
            p += (int) tokenLength[0];
        }
        long[] length = readVarint(w, p);
        if (length == null) {
            return null;
        }
        p = (int) length[1];
        if (length[0] < env.pnWidth || length[0] > (long) (w.length - p)) {
            return null;
        }
        env.rawPn = rawNumber(w, p, env.pnWidth);
        int payloadStart = p + env.pnWidth;
        env.payload = Arrays.copyOfRange(w, payloadStart, p + (int) length[0]);
        env.next = p + (int) length[0];
        return env;
    }
    if ((first & 0x40) == 0 || (first & 0x18) != 0) {
        return null;
    }
    env.level = A;
    env.phase = (first >>> 2) & 1;
    env.pnWidth = (first & 0x03) + 1;
    int p = pos + 1;
    if (p + localCidWidth > w.length) {
        return null;
    }
    env.dcid = Arrays.copyOfRange(w, p, p + localCidWidth);
    p += localCidWidth;
    if (p + env.pnWidth > w.length) {
        return null;
    }
    env.rawPn = rawNumber(w, p, env.pnWidth);
    env.payload = Arrays.copyOfRange(w, p + env.pnWidth, w.length);
    env.next = w.length;
    return env;
}

